const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Pedrógão Grande, Portugal. A major wildfire event occurred here in June 2017.
  const aoi = ee.Geometry.Point([-8.1415, 39.9142]).buffer(10000); // 10km buffer
  const startDate = '2017-06-16';
  const endDate = '2017-06-21'; // Inclusive end date for filterDate

  // 2. Data Acquisition & Check
  // Use MODIS Thermal Anomalies/Fire dataset, which is ideal for detecting active fires.
  const fireCollection = ee.ImageCollection('MODIS/061/MCD14ML')
    .filterDate(startDate, endDate)
    .filterBounds(aoi);

  // Get the number of fire detection points.
  const fireCount = fireCollection.size().getInfo();

  // The MCD14ML collection contains a 'confidence' band. We can calculate the mean confidence.
  // A count is sufficient, but mean confidence adds extra evidence.
  let meanConfidence = 0;
  if (fireCount > 0) {
      const confidenceImage = fireCollection.select('confidence').mosaic();
      const stats = confidenceImage.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: aoi,
          scale: 1000, // MODIS fire product is at 1km resolution
          maxPixels: 1e9
      });
      // getInfo() can return null if no pixels are in the region
      const confidenceVal = stats.get('confidence').getInfo();
      if (confidenceVal !== null) {
          meanConfidence = confidenceVal;
      }
  }

  // 3. Validation & Final Answer
  console.log(`Query Period: ${startDate} to ${endDate}`);
  console.log(`Location: Pedrógão Grande, Portugal`);
  console.log(`MODIS fire detections found: ${fireCount}`);
  if (fireCount > 0) {
      console.log(`Mean Fire Confidence: ${meanConfidence.toFixed(2)}%`);
  }

  if (fireCount > 0) {
    console.log("Evidence: A significant number of fire hotspots were detected by MODIS.");
    console.log("A");
  } else {
    console.log("Evidence: No fire hotspots were detected by MODIS in the specified area and time.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    // Handle potential GEE errors during initialization or execution
    if (e.message.includes("Image.load") || e.message.includes("Collection.load") || e.message.includes("invalid band") || e.message.includes("not a function")) {
        console.log("D");
    } else if (e.message.includes("computation timed out")) {
        console.log("D");
    } else {
        console.log("D");
    }
});
